function calcPrice({mode,type,travelers,rooms,days,roomDays,separateRoomDays,trip,returnTrip}){
 if(!trip)return 0;
 const count=Math.max(1,Number(travelers||1));
 const stayDays=Math.max(1,Number(days||1));
 const roomCount=Math.max(1,Number(rooms||1));
 const one=n(trip.price_one_way);
 const returnOnly=n(trip.price_return_only??trip.price_one_way);
 const roundTrip=n(trip.price_round_trip??trip.price_no_accommodation);
 const legacyNone=n(trip.price_no_accommodation),legacyShared=n(trip.price_shared);
 const sharedDailyConfigured=trip.price_shared_daily!==null&&trip.price_shared_daily!==undefined&&String(trip.price_shared_daily)!=='';
 const sharedDaily=n(trip.price_shared_daily);
 const roomRate=n(trip.price_private_room||trip.price_private_double||trip.price_private_single||trip.price_private_triple||trip.price_private_quad||trip.price_private_quint);
 const privateDayUnits=separateRoomDays?normalizeRoomDays(roomCount,roomDays,stayDays).reduce((sum,x)=>sum+x,0):roomCount*stayDays;
 const privateCost=type==='private'?roomRate*privateDayUnits:0;
 const sharedCost=type==='shared'&&sharedDailyConfigured?sharedDaily*stayDays*count:0;
 if(mode==='oneway')return one*count+sharedCost+privateCost;
 if(mode==='returnonly')return returnOnly*count+sharedCost+privateCost;
 // وضع «ذهاب + عودة من رحلة أخرى» يحتفظ بمنطقه القديم للرحلات التي لديها أسعار Legacy.
 if(mode==='separate'){
  const returnLeg=n(returnTrip?.price_one_way)*count;
  if(type==='shared'){
   if(sharedDailyConfigured)return legacyNone*count+sharedCost+returnLeg;
   if(legacyShared>0)return legacyShared*count+returnLeg;
   return legacyNone*count+returnLeg;
  }
  return legacyNone*count+privateCost+returnLeg;
 }
 if(mode==='roundtrip'){
  if(type==='shared'&&!sharedDailyConfigured)return legacyShared*count;
  return roundTrip*count+sharedCost+privateCost;
 }
 return 0;
}
